// UpdateNewValues updates the mutable fields using the new values that were set on create except the ID field.
// Using this option is equivalent to using:
//
//	client.ContactImport.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(contactimport.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *ContactImportUpsertOne) UpdateNewValues() *ContactImportUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		if _, exists := u.create.mutation.ID(); exists {
			s.SetIgnore(contactimport.FieldID)
		}
		if _, exists := u.create.mutation.CreatedAt(); exists {
			s.SetIgnore(contactimport.FieldCreatedAt)
		}
		if _, exists := u.create.mutation.MemberName(); exists {
			s.SetIgnore(contactimport.FieldMemberName)
		}
		if _, exists := u.create.mutation.Delimiter(); exists {
			s.SetIgnore(contactimport.FieldDelimiter)
		}
		if _, exists := u.create.mutation.Header(); exists {
			s.SetIgnore(contactimport.FieldHeader)
		}
		if _, exists := u.create.mutation.Size(); exists {
			s.SetIgnore(contactimport.FieldSize)
		}
		if _, exists := u.create.mutation.RowCount(); exists {
			s.SetIgnore(contactimport.FieldRowCount)
		}
		if _, exists := u.create.mutation.MalformedRows(); exists {
			s.SetIgnore(contactimport.FieldMalformedRows)
		}
	}))
	return u
}

